/**
 * Module loading and the raw C surface.
 *
 * The WASM glue (`../build/hx.mjs`) is generated by `npm run build:wasm` and has
 * no type declarations, so it is imported through a non-literal specifier and
 * wrapped in the `RawApi` interface below. Everything above this file sees
 * ordinary TypeScript.
 */
import type { Ptr } from "./types.js";

export interface RawApi {
  parse(html: string, len: number, encoding: string): Ptr;
  dropComments(doc: Ptr): void;
  docFree(doc: Ptr): void;
  root(doc: Ptr): Ptr;

  type(n: Ptr): number;
  name(n: Ptr): Ptr;
  parent(n: Ptr): Ptr;
  text(n: Ptr): Ptr;
  ownText(n: Ptr): Ptr;

  childCount(n: Ptr): number;
  childAt(n: Ptr, i: number): Ptr;

  attrCount(n: Ptr): number;
  attrName(n: Ptr, i: number): Ptr;
  attrValue(n: Ptr, i: number): Ptr;

  path(n: Ptr): Ptr;
  freeStr(p: Ptr): void;

  xpath(doc: Ptr, expr: string): Ptr;
  xpathAt(node: Ptr, expr: string): Ptr;
  xpathSize(o: Ptr): number;
  xpathItem(o: Ptr, i: number): Ptr;
  xpathFree(o: Ptr): void;

  utf8(p: Ptr): string;
  byteLength(s: string): number;
}

let apiPromise: Promise<RawApi> | null = null;

/** Loads and initialises the module once; subsequent calls reuse it. */
export function loadApi(): Promise<RawApi> {
  if (!apiPromise) {
    apiPromise = initApi();
    // A failed load should be retryable rather than permanently poisoned.
    apiPromise.catch(() => {
      apiPromise = null;
    });
  }
  return apiPromise;
}

async function initApi(): Promise<RawApi> {
  // Non-literal specifier: the artifact is generated post-install.
  const url = new URL("../build/hx.mjs", import.meta.url).href;

  let mod: any;
  try {
    mod = await import(url);
  } catch (cause) {
    throw new Error(
      "WASM artifact not found. Run `npm run build:wasm` in packages/libxml2-html-wasm.",
      { cause },
    );
  }

  const factory = mod.default ?? mod;
  const M: any = typeof factory === "function" ? await factory() : factory;
  const cw = (name: string, ret: any, args: any[]): any => M.cwrap(name, ret, args);

  return {
    parse: cw("hx_parse", "number", ["string", "number", "string"]),
    dropComments: cw("hx_drop_comments", null, ["number"]),
    docFree: cw("hx_doc_free", null, ["number"]),
    root: cw("hx_root", "number", ["number"]),

    type: cw("hx_type", "number", ["number"]),
    name: cw("hx_name", "number", ["number"]),
    parent: cw("hx_parent", "number", ["number"]),
    text: cw("hx_text", "number", ["number"]),
    ownText: cw("hx_own_text", "number", ["number"]),

    childCount: cw("hx_child_count", "number", ["number"]),
    childAt: cw("hx_child_at", "number", ["number", "number"]),

    attrCount: cw("hx_attr_count", "number", ["number"]),
    attrName: cw("hx_attr_name", "number", ["number", "number"]),
    attrValue: cw("hx_attr_value", "number", ["number", "number"]),

    path: cw("hx_path", "number", ["number"]),
    freeStr: cw("hx_free_str", null, ["number"]),

    xpath: cw("hx_xpath", "number", ["number", "string"]),
    xpathAt: cw("hx_xpath_at", "number", ["number", "string"]),
    xpathSize: cw("hx_xpath_size", "number", ["number"]),
    xpathItem: cw("hx_xpath_item", "number", ["number", "number"]),
    xpathFree: cw("hx_xpath_free", null, ["number"]),

    utf8: (p: Ptr) => (p ? M.UTF8ToString(p) : ""),
    byteLength: (s: string) => M.lengthBytesUTF8(s),
  };
}

/** Reads an allocated C string and frees it. */
export function takeString(api: RawApi, ptr: Ptr): string {
  if (!ptr) return "";
  const value = api.utf8(ptr);
  api.freeStr(ptr);
  return value;
}
